frappe.web_form.set_df_property('event_detail', 'read_only', 1);
frappe.web_form.set_df_property('event', 'read_only', 1);
frappe.web_form.set_df_property('school', 'read_only', 1);
frappe.web_form.set_df_property('starts_on', 'read_only', 1);
frappe.web_form.set_df_property('student', 'read_only', 1);
frappe.web_form.set_df_property('class', 'read_only', 1);
frappe.web_form.on('event_detail', (field, value) => {
    frappe.call({
        method: 'edu_quality.edu_quality.doctype.event_participant.event_participant.get_data',
        args: {
            event_detail: value,
        },
        callback: function(r) {
            if (r.message) {
                let event_detail = r.message;
                frappe.web_form.set_value('event', event_detail.event);
                frappe.web_form.set_value('school', event_detail.school);
                frappe.web_form.set_value('starts_on', event_detail.event_starts_on);
            }
        }
    })
})

frappe.web_form.on('refno', (field, value) => {
    setTimeout(() => {
        let event_detail = frappe.web_form.get_value('event_detail');
        let school = frappe.web_form.get_value('school');
        frappe.call({  
            method: 'edu_quality.edu_quality.doctype.event_participant.event_participant.get_data',
            args: {
                refno: value,
                school: school
            },
            callback: function(r) {
                if (r.message) {
                    let student = r.message;
                    frappe.web_form.set_value('student', student.name);
                    frappe.web_form.set_value('student_name', student.student_name);
                    frappe.web_form.set_value('class', student.program);
                }
            }
        })
    }, 1000)
})

